export function buildTriviaDeck(selectedCategories: TriviaCategory[], questionsPerPlayer: number, playerCount: number) {
  const allowed = TRIVIA_QUESTIONS.filter((question) => selectedCategories.includes(question.category));
  const targetCount = questionsPerPlayer * playerCount;

  if (allowed.length === 0) {
    return [];
  }

  const deck: TriviaQuestion[] = [];

  while (deck.length < targetCount) {
    const source = shuffleQuestions(allowed);
    for (const question of source) {
      if (deck.length >= targetCount) {
        break;
      }
      deck.push(question);
    }
  }

  return deck;
}

function shuffleQuestions(input: TriviaQuestion[]) {
  const copy = [...input];
  for (let index = copy.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [copy[index], copy[swapIndex]] = [copy[swapIndex], copy[index]];
  }
  return copy;
}

let questionsBySwedishPrompt: Map<string, TriviaQuestion> | null = null;

/**
 * Turns store the Swedish question/answer text. Look the question up by its Swedish
 * prompt and return the text in the player's language (falls back to the stored text).
 */
export function localizeTriviaTurn(questionText: string, answerText: string, language: TriviaLanguage) {
  if (language !== "en") {
    return { question: questionText, answer: answerText };
  }
  if (!questionsBySwedishPrompt) {
    questionsBySwedishPrompt = new Map(TRIVIA_QUESTIONS.map((question) => [question.prompt.trim(), question]));
  }
  const match = questionsBySwedishPrompt.get(questionText.trim());
  if (!match) {
    return { question: questionText, answer: answerText };
  }
  return { question: match.promptEn, answer: match.answerEn };
}
